%  See also FIT, CFIT, SFIT.

%  Auto-generated by MATLAB on 24-Feb-2026 13:36:28


%% Fit: 'T2'.
[xData, yData] = prepareCurveData( times, signals);

% Set up fittype and options.
ft = fittype( 'S0*exp(-R2*x)+c', 'independent', 'x', 'dependent', 'y' );
opts = fitoptions( 'Method', 'NonlinearLeastSquares' );
opts.Display = 'Off';
opts.Lower = [0 0 -Inf];
opts.StartPoint = [80 6 2.5];

% Fit model to data.
[fitresult, gof] = fit( xData, yData, ft, opts );

% Plot fit with data.
figure( 'Name', 'T2' );
h = plot( fitresult, xData, yData );
legend( h, 'signals vs. times', 'T2', 'Location', 'NorthEast', 'Interpreter', 'none' );
% Label axes
xlabel( 'times', 'Interpreter', 'none' );
ylabel( 'signals', 'Interpreter', 'none' );
grid on

